// Find WaterController and check its references
var wc = GameObject.FindFirstObjectByType<WaterController>();
if(wc==null){Debug.LogError("WaterController not found!");return;}
Debug.Log("WaterController on: "+wc.gameObject.name+" (path check below)");
Debug.Log("  waterParticles: "+(wc.waterParticles!=null ? wc.waterParticles.gameObject.name+" at "+wc.waterParticles.transform.position : "NULL!"));
Debug.Log("  spillParticles: "+(wc.spillParticles!=null ? wc.spillParticles.gameObject.name+" at "+wc.spillParticles.transform.position : "NULL!"));
Debug.Log("  rotationTracker: "+(wc.rotationTracker!=null ? "OK" : "NULL!"));

// Check RehabCanvas
var rc = GameObject.Find("RehabCanvas");
if(rc!=null) Debug.Log("RehabCanvas scale="+rc.transform.localScale+" rot="+rc.transform.eulerAngles+" pos="+rc.transform.position);

// Check ScoreCanvas
var sc = GameObject.Find("ScoreCanvas");
if(sc!=null) Debug.Log("ScoreCanvas scale="+sc.transform.localScale);

// PlantRowManager check
var prm = GameObject.FindFirstObjectByType<PlantRowManager>();
if(prm!=null){
    Debug.Log("PlantRowManager found, plants count: "+prm.plants.Length);
    Debug.Log("  waterSpout ref: "+(prm.waterSpout!=null ? prm.waterSpout.gameObject.name : "NULL"));
}

// Check CanGrabNotifier
var cgn = GameObject.FindFirstObjectByType<CanGrabNotifier>();
Debug.Log("CanGrabNotifier: "+(cgn!=null ? cgn.gameObject.name : "NULL"));

// Check ForearmRotationTracker
var frt = GameObject.FindFirstObjectByType<ForearmRotationTracker>();
Debug.Log("ForearmRotationTracker on: "+(frt!=null ? frt.gameObject.name : "NULL"));

Debug.Log("Diagnosis complete.");
